#[test]
fn valid_delegation_and_receipt_round_trip_through_json() {
    let delegation = delegation();
    let receipt = DelegationReceipt {
        delegation_id: delegation.delegation_id.clone(),
        issuer_principal_id: delegation.issuer_principal_id.clone(),
        delegatee_session_id: delegation.delegatee_session_id.clone(),
        scope: delegation.scope.clone(),
        occurred_at: 1_700_000_030,
        status: DelegationReceiptStatus::Granted,
        reason: None,
    };

    assert_eq!(delegation.validate(), Ok(()));
    assert_eq!(receipt.validate(), Ok(()));

    let delegation_json = serde_json::to_string(&delegation).expect("serialize delegation");
    let receipt_json = serde_json::to_string(&receipt).expect("serialize receipt");

    assert_eq!(
        serde_json::from_str::<HumanDelegation>(&delegation_json).expect("deserialize delegation"),
        delegation
    );
    assert_eq!(
        serde_json::from_str::<DelegationReceipt>(&receipt_json).expect("deserialize receipt"),
        receipt
    );
}

#[test]
fn blank_issuer_principal_is_refused() {
    let mut delegation = delegation();
    delegation.issuer_principal_id = " ".to_string();

    assert_eq!(
        delegation.validate(),
        Err(DelegationError::EmptyField {
            field: "issuer_principal_id",
        })
    );
}

#[test]
