#[test]
fn delegation_requires_at_least_one_routine_action() {
    let mut delegation = delegation();
    delegation.allowed_actions.clear();

    assert_eq!(
        delegation.validate(),
        Err(DelegationError::NoDelegatedActions)
    );
}

#[test]
fn duplicate_routine_action_is_refused() {
    let mut delegation = delegation();
    delegation
        .allowed_actions
        .push(DelegatedAction::RetrieveContext);

    assert_eq!(
        delegation.validate(),
        Err(DelegationError::DuplicateDelegatedAction {
            action: DelegatedAction::RetrieveContext,
        })
    );
}

#[test]
fn delegated_action_vocabulary_excludes_privileged_actions() {
    const SOURCE: &str = include_str!("../src/delegation.rs");
    let action_block = SOURCE
        .split("pub enum DelegatedAction")
        .nth(1)
        .and_then(|tail| tail.split("\n}").next())
        .expect("DelegatedAction enum body");
    let variants: Vec<&str> = action_block
        .lines()
        .map(str::trim)
        .filter(|line| !line.is_empty() && !line.starts_with("//") && *line != "{")
        .map(|line| line.trim_end_matches(','))
        .collect();

    for privileged_action in [
        "Policy",
        "Constitution",
        "Waiver",
        "Authority",
        "Identity",
        "Key",
        "Export",
        "TerminateForce",
        "Execute",
        "Shell",
        "Command",
    ] {
        assert!(
            !variants.contains(&privileged_action),
            "delegation action vocabulary must remain routine-only: {privileged_action}"
        );
    }
}

